import process from "node:process";

import { createEnv } from "@t3-oss/env-core";
import { z } from "zod";

console.debug("⏳ [ENV_WEB_SERVER] Loading environment variables...", {
  // https://developers.cloudflare.com/changelog/post/2025-06-10-default-env-vars/
  SOURCE_COMMIT: process.env.WORKERS_CI_COMMIT_SHA
});

export const ENV_WEB_SERVER = createEnv({
  emptyStringAsUndefined: true,
  runtimeEnv: process.env,
  server: {
    NODE_ENV: z.enum(["development", "production"]).default("development"),
    SOURCE_COMMIT: z.string().min(1).default("unknown"), // autogenerated by Coolify, needs to be manually set otherwise
    IS_BUILD: z.stringbool().default(false), // set to 'true' during build, can be used to conditionally disable features that should only run during runtime and not during build/prerendering
    R2_PUBLIC_BASE_URL:
      process.env.IS_BUILD === "true" ? z.url().default("https://placeholder.r2.dev") : z.url(),
    FILES_API_SECRET: z.string().min(1).default("dev-only-secret-do-not-use-in-production")
  }
});

console.debug("✅ [ENV_WEB_SERVER] Successfully loaded environment variables.");
